// Offline actual-order cohort study; no credentials/order/notifier imports.
import fs from 'node:fs/promises';
import crypto from 'node:crypto';
import assert from 'node:assert/strict';
const dir='data/research/margin3-market-volume-20261107', prior='data/research/margin3-whales-20261107', S=300000;
const read=async p=>JSON.parse(await fs.readFile(p,'utf8')), save=async(p,x)=>fs.writeFile(p,JSON.stringify(x,null,2)), hash=x=>crypto.createHash('sha256').update(x).digest('hex');
await fs.mkdir(dir+'/raw',{recursive:true});
const inputBytes=await fs.readFile(prior+'/results.json'), input=JSON.parse(inputBytes), all=input.records.filter(r=>r.signalSource==='coin-level-entry-watch'), rows=all.filter(r=>r.clean);
let protocol;
try{protocol=await read(dir+'/protocol.json');assert.equal(protocol.inputHash,hash(inputBytes));}catch(e){if(e.code!=='ENOENT')throw e;protocol={version:'MARGIN3_MARKET_VOLUME_V1_20261107',createdAt:Date.now(),inputHash:hash(inputBytes),cohort:'Frozen actual margin3USDT coin-level-entry-watch: 360 closed, 341 single-entry clean, 275 known submission times (all SHORT); secondary actual-fill 341. Actual leverage and actual net outcomes, no hypothetical rerouting.',features:'Last 49 contiguous closed 5m candles, close+5sec<=decision. 15m quote volume / (mean previous20 5m quote volumes *3), 15m taker buy quote share, coin15m/1h/4h returns, BTC1h/4h returns, close position in15m range.',filters:['VOLUME: volumeRatio>=1.5','FLOW: taker volume same side>=55%','COIN_TREND: coin1h signed>0','BTC_TREND: BTC1h signed>0','FLOW_VOLUME: FLOW AND VOLUME','CONFLUENCE: FLOW_VOLUME AND COIN_TREND AND BTC_TREND'],additional:'Crowd opposite>=60 alone and intersect six filters, ONLY matched pre-order crowd subgroup. Whale+Smart same>=60 descriptive extension on that subgroup.',split:'Per mode and direction, final30% chronologically by decision timestamp = temporal check. Earlier70% train; exclude train orders closed at/after split. Thresholds fixed before data retrieval/results, not optimized; retrospective exploratory holdout, not prospective validation.',scope:'BTC is a market proxy, not market-wide breadth. No historical whale cost/PnL/OI/model reconstruction here. Current snapshots never used for old orders. Original recorded fees/funding/net PnL used. No rule/Discord/execution changes.'};await save(dir+'/protocol.json',protocol);}
const symbols=new Map();
async function series(symbol){if(symbols.has(symbol))return symbols.get(symbol);const map=new Map();for(const path of [dir+'/raw/'+symbol+'.json','data/heatmap-market-raw-cache/'+symbol+'.json']){try{const x=await read(path);for(const r of x.price??[])if(!map.has(+r[0]))map.set(+r[0],r);}catch(e){if(e.code!=='ENOENT')throw e;}}symbols.set(symbol,map);return map;}
let next=0,calls=0,errors=[];
const sleep=ms=>new Promise(r=>setTimeout(r,ms));
async function fetchPage(symbol,from,end){await sleep(Math.max(0,next-Date.now()));next=Date.now()+2000;const q=new URLSearchParams({symbol,interval:'5m',startTime:from,endTime:end-1,limit:100});let resp;for(let attempt=0;attempt<2;attempt++){try{resp=await fetch('https://fapi.binance.com/fapi/v1/klines?'+q,{signal:AbortSignal.timeout(15000),redirect:'error'});break;}catch(e){if(attempt)throw e;await sleep(1500);}}calls++;if([403,418,429].includes(resp.status))throw Error('STOP_'+resp.status);if(!resp.ok)throw Error('HTTP_'+resp.status);if(+resp.headers.get('x-mbx-used-weight-1m')>1000)throw Error('STOP_WEIGHT');const data=await resp.json();if(!Array.isArray(data))throw Error('INVALID_PAGE');return data;}
async function window(symbol,t){const end=Math.floor((t-5000)/S)*S,from=end-49*S,map=await series(symbol);let complete=true;for(let x=from;x<end;x+=S)if(!map.has(x)){complete=false;break;}if(!complete){try{for(const r of await fetchPage(symbol,from,end))if(!map.has(+r[0]))map.set(+r[0],r);await save(dir+'/raw/'+symbol+'.json',{symbol,price:[...map.values()].sort((a,b)=>a[0]-b[0]),savedAt:Date.now()});}catch(e){if(e.message.startsWith('STOP_'))throw e;errors.push({symbol,t,error:e.message});return null;}}
const out=[];for(let x=from;x<end;x+=S){const r=map.get(x);if(!r||+r[6]+5000>t||!r.slice(1,5).every(v=>Number.isFinite(+v)&&+v>0)||![7,10].every(i=>Number.isFinite(+r[i]))||+r[7]<0||+r[10]<0||+r[10]>+r[7]+1e-6)return null;out.push(r);}return out;}
function features(p,b,t){const recent=p.slice(-3),prev=p.slice(-23,-3),sum=(a,i)=>a.reduce((s,r)=>s+ +r[i],0),vol=sum(recent,7),avg=sum(prev,7)/20,hi=Math.max(...recent.map(r=>+r[2])),lo=Math.min(...recent.map(r=>+r[3])),ret=(a,k)=>(+a.at(-1)[4]/+a.at(-1-k)[4]-1)*100;return{at:t,lastClose:+p.at(-1)[6],btcLastClose:+b.at(-1)[6],volumeRatio:avg>0?vol/(3*avg):null,quoteVolume15m:vol,takerBuyPct:vol>0?sum(recent,10)/vol*100:null,coin15m:ret(p,3),coin1h:ret(p,12),coin4h:ret(p,48),btc1h:ret(b,12),btc4h:ret(b,48),closePosition:hi>lo?(+p.at(-1)[4]-lo)/(hi-lo)*100:50};}
const enriched=[];let done=0;
for(const r of rows){const o={...r,market:{}};for(const mode of ['preorder','atFill']){const t=mode==='preorder'?r.submittedAt:Date.parse(r.filledAt);if(!Number.isFinite(t)){o.market[mode]={status:'NO_SUBMISSION_TIME'};continue;}const p=await window(r.symbol,t),b=await window('BTCUSDT',t);o.market[mode]=p&&b?{status:'OK',...features(p,b,t)}:{status:'MISSING_CANDLES'};}enriched.push(o);done++;if(done%20===0){await save(dir+'/progress.json',{done,total:rows.length,calls,errors});console.log(JSON.stringify({done,total:rows.length,calls,errors:errors.length}));}}
function stats(xs){const n=xs.length,w=xs.filter(r=>r.netRealizedPnlUsdt>0).length,net=xs.reduce((s,r)=>s+r.netRealizedPnlUsdt,0);return{n,coins:new Set(xs.map(r=>r.symbol)).size,winPct:n?w/n*100:null,net,meanRoe:n?xs.reduce((s,r)=>s+r.realizedRoePct,0)/n:null,meanNetReturnPct:n?xs.reduce((s,r)=>s+r.netRealizedPnlUsdt/r.filledNotionalUsdt*100,0)/n:null};}
const defs={VOLUME:(f,d)=>f.volumeRatio>=1.5,FLOW:(f,d)=>(d===1?f.takerBuyPct:100-f.takerBuyPct)>=55,COIN_TREND:(f,d)=>f.coin1h*d>0,BTC_TREND:(f,d)=>f.btc1h*d>0};defs.FLOW_VOLUME=(f,d)=>defs.VOLUME(f,d)&&defs.FLOW(f,d);defs.CONFLUENCE=(f,d)=>defs.FLOW_VOLUME(f,d)&&defs.COIN_TREND(f,d)&&defs.BTC_TREND(f,d);
const passes=(r,mode,k)=>{const f=r.market[mode];return f.status==='OK'&&Number.isFinite(f.volumeRatio)&&Number.isFinite(f.takerBuyPct)&&defs[k](f,r.direction==='LONG'?1:-1);};
function comparison(xs,fn,split){const kept=xs.filter(fn),rejected=xs.filter(r=>!fn(r));assert.equal(kept.length+rejected.length,xs.length);return{kept:stats(kept),rejected:stats(rejected),train:stats(kept.filter(r=>r.market[split.mode].at<split.at&&Date.parse(r.closedAt)<split.at)),test:stats(kept.filter(r=>r.market[split.mode].at>=split.at)),byLeverage:Object.fromEntries([3,5].map(l=>[l,stats(kept.filter(r=>r.leverage===l))]))};}
const summary={};
for(const mode of ['preorder','atFill']){summary[mode]={};for(const side of ['SHORT','LONG']){const xs=enriched.filter(r=>r.direction===side&&r.market[mode].status==='OK'&&Number.isFinite(r.market[mode].volumeRatio)&&Number.isFinite(r.market[mode].takerBuyPct)).sort((a,b)=>a.market[mode].at-b.market[mode].at),split={mode,at:xs.length?xs[Math.floor(xs.length*.7)].market[mode].at:Infinity};const known=xs.filter(r=>r[mode].status==='OK'),crowd=r=>r[mode].crowdOpposite>=60;summary[mode][side]={baseline:stats(xs),split:split.at,train:stats(xs.filter(r=>r.market[mode].at<split.at&&Date.parse(r.closedAt)<split.at)),test:stats(xs.filter(r=>r.market[mode].at>=split.at)),purged:xs.filter(r=>r.market[mode].at<split.at&&Date.parse(r.closedAt)>=split.at).length,filters:Object.fromEntries(Object.keys(defs).map(k=>[k,comparison(xs,r=>passes(r,mode,k),split)])),crowd:{baseline:stats(known),opposite60:comparison(known,crowd,split),combined:Object.fromEntries(Object.keys(defs).map(k=>[k,comparison(known,r=>crowd(r)&&passes(r,mode,k),split)])),whaleSmartSame60AndCrowd:comparison(known,r=>crowd(r)&&r[mode].whaleAligned>=60&&r[mode].smartAligned>=60,split)}};}}
const coverage={closed:all.filter(r=>r.positionStatus==='CLOSED').length,clean:rows.length,excluded:all.filter(r=>r.positionStatus==='CLOSED'&&!r.clean).length,noSubmit:rows.filter(r=>!r.submittedAt).length,beforeJournal:rows.filter(r=>r.submittedAt&&r.submittedAt<input.journalRange.firstJournal).length,matched:rows.filter(r=>r.preorder.status==='OK').length,afterJournalMissing:rows.filter(r=>r.submittedAt>=input.journalRange.firstJournal&&r.preorder.status!=='OK').length,market:Object.fromEntries(['preorder','atFill'].map(m=>[m,Object.fromEntries(['OK','NO_SUBMISSION_TIME','MISSING_CANDLES'].map(s=>[s,enriched.filter(r=>r.market[m].status===s).length]))]))};
for(const r of enriched)for(const mode of ['preorder','atFill']){const f=r.market[mode];if(f.status==='OK')assert.ok(f.lastClose+5000<=f.at&&f.btcLastClose+5000<=f.at);}
const rawHashes={};for(const symbol of symbols.keys()){const price=[...symbols.get(symbol).values()].sort((a,b)=>a[0]-b[0]);await save(dir+'/raw/'+symbol+'.json',{symbol,price});rawHashes[symbol]=hash(await fs.readFile(dir+'/raw/'+symbol+'.json'));}
await save(dir+'/results.json',{protocol,coverage,summary,records:enriched});await save(dir+'/summary.json',{protocol,coverage,summary});await save(dir+'/validation.json',{status:'PASS',records:enriched.length,noFutureCandles:true,candleAvailabilityLagMs:5000,contiguousBarsRequired:49,inputHash:hash(inputBytes),rawHashes,calls,errors,noRuntimeChanges:true});console.log(JSON.stringify({stage:'COMPLETE',coverage,summary}));

